const deepEntry = (entry, venue, index) => Object.freeze({
  ...entry, venueId: venue.id, section: Math.floor(index / 6), slot: index % 6,
  unlockStage: venue.firstStage,
  name: Object.freeze(entry.name), detail: Object.freeze(entry.detail),
  narrative: Object.freeze(entry.narrative), sourceIds: Object.freeze(entry.sourceIds),
});
export const CULTURAL_DETAILS = Object.freeze(VENUES.flatMap(venue => BY_VENUE[venue.id].map((entry, index) => deepEntry(entry, venue, index))));
const DETAILS_BY_ID = new Map(CULTURAL_DETAILS.map(entry => [entry.id, entry]));
export const detailsForVenue = venueId => CULTURAL_DETAILS.filter(entry => entry.venueId === venueId);
export const getCulturalDetail = id => DETAILS_BY_ID.get(id) || null;
